// ── KpiCard ──────────────────────────────────────────────────────────────────
// One cell in the KPI strip bar. `isFirst` triggers the blue-tinted highlight
// on the primary metric; `isEarly` applies the faint emerald tint on items 2-4.
// `tip` is rendered as a native title tooltip (no extra DOM cost).
function KpiCard({ label, sublabel, value, color, tip, isFirst = false, isEarly = false }) {
  const bg = isFirst
    ? "rgba(var(--clr-blue-rgb),0.08)"
    : isEarly
    ? "rgba(var(--clr-emerald-rgb),0.04)"
    : "transparent";
  const labelColor = color;
  return (
    <div
      title={tip || ""}
      style={{
        padding: "6px 10px",
        borderRadius: 8,
        border: "1px solid var(--border-subtle)",
        minWidth: 0,
        textAlign: "center",
        boxSizing: "border-box",
        cursor: "help",
        background: bg,
      }}
    >
      <div
        className="cpf-kpi-label"
        style={{
          fontSize: 11,
          fontWeight: 600,
          color: labelColor,
          marginBottom: 1,
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
        }}
      >
        {label}
      </div>
      {sublabel && (
        <div
          style={{
            fontSize: 9,
            fontWeight: 500,
            color: "var(--text-muted)",
            marginBottom: 3,
            whiteSpace: "nowrap",
            overflow: "hidden",
            textOverflow: "ellipsis",
          }}
        >
          {sublabel}
        </div>
      )}
      <div
        className="cpf-kpi-value"
        style={{ fontSize: 17, fontWeight: 900, color, fontFamily: "monospace", textShadow: "var(--shadow-kpi)" }}
      >
        {value}
      </div>
    </div>
  );
}

// ── TagPill ───────────────────────────────────────────────────────────────────
// Coloured pill / badge span used throughout the UI. All colour props accept
// any valid CSS value (var tokens, hex, rgba).
// `size` defaults to 10 (px); pass a number.
function TagPill({ color, bg, border, size = 10, bold = true, uppercase = false, children, style: extraStyle }) {
  return (
    <span
      style={{
        ...STYLES.tagPill,
        fontSize: size,
        fontWeight: bold ? 700 : 400,
        color,
        background: bg,
        border: border ? `1px solid ${border}` : undefined,
        textTransform: uppercase ? "uppercase" : undefined,
        ...extraStyle,
      }}
    >
      {children}
    </span>
  );
}

// ── SidebarSectionHeader ──────────────────────────────────────────────────────
// Renders the clickable header row of a sidebar section (icon, label, badge,
// chevron) plus an optional one-line hint shown when the section is collapsed.
//
// Props:
//   id            – section key used in aria-controls
//   label         – display text for the section title
//   icon          – pre-rendered React element (icon with size/colour already set)
//   color         – accent colour for label text (CSS value)
//   activeBg      – header background when isOpen is true
//   badge         – optional JSX after the label (count chips, warning icons)
//   isOpen        – whether the section is currently expanded
//   onToggle      – () => void callback for click / keyboard activation
//   collapsedHint – UX-P1: short string shown beneath the header when collapsed
//                   e.g. "VC3A · RSTU · VCMA · MRSS". Helps users find fields
//                   without expanding every section. Omit for always-open sections.
function SidebarSectionHeader({ id, label, icon, color, activeBg, badge, isOpen, onToggle, collapsedHint }) {
  return (
    <>
      <div
        onClick={onToggle}
        tabIndex={0}
        className="sidebar-section-header"
        role="button"
        aria-expanded={isOpen}
        aria-controls={`section-body-${id}`}
        onKeyDown={e => {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onToggle(); }
        }}
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "12px 16px",
          cursor: "pointer",
          userSelect: "none",
          background: isOpen ? activeBg : "transparent",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          {icon}
          <span style={{ fontSize: 13, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.05em", color }}>
            {label}
          </span>
          {badge}
        </div>
        <span style={{ fontSize: 11, color: "var(--text-muted)", fontWeight: 700 }}>
          {isOpen ? "▲" : "▼"}
        </span>
      </div>
      {/* UX-P1: Collapsed hint — quick-scan summary of what's inside without expanding */}
      {!isOpen && collapsedHint && (
        <div style={{ padding: "0 16px 10px 42px", fontSize: 11, color: "var(--text-subtle)", fontStyle: "italic", lineHeight: 1.5, marginTop: -4 }}>
          {collapsedHint}
        </div>
      )}
    </>
  );
}


// Wraps one collapsible sidebar panel. The header row handles click, keyboard,
// and accessibility. The body is only mounted when `isOpen` is true.
//
// Props:
//   id        – section key matching openSections (used in aria attrs only)
//   label     – display text for the section title
//   icon      – pre-rendered React element (icon component with size/colour)
//   color     – accent colour for label text and icon (CSS value)
//   activeBg  – background applied to the header row when isOpen is true
//   badge     – optional JSX rendered after the label (count chips, warnings)
//   isOpen    – boolean: is the section currently expanded?
//   onToggle  – () => void: called when the user clicks or presses Enter/Space
//   children  – section body content (only rendered when isOpen)
//   bodyPad   – body padding override (default "0 16px 16px")
//   wrapStyle – extra style for the outer wrapper div
function SidebarSection({
  id,
  label,
  icon,
  color,
  activeBg,
  badge,
  isOpen,
  onToggle,
  children,
  bodyPad = "0 16px 16px",
  wrapStyle,
}) {
  return (
    <div
      style={{
        background: "var(--bg-panel)",
        border: "1px solid var(--border-subtle)",
        borderRadius: 16,
        overflow: "visible",
        ...wrapStyle,
      }}
    >
      {/* ── Header row ── */}
      <div
        onClick={onToggle}
        tabIndex={0}
        className="sidebar-section-header"
        role="button"
        aria-expanded={isOpen}
        aria-controls={`section-body-${id}`}
        onKeyDown={e => {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onToggle(); }
        }}
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "12px 16px",
          cursor: "pointer",
          userSelect: "none",
          background: isOpen ? activeBg : "transparent",
          borderRadius: isOpen ? "16px 16px 0 0" : 16,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          {icon}
          <span style={{ fontSize: 13, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.05em", color }}>
            {label}
          </span>
          {badge}
        </div>
        <span style={{ fontSize: 11, color: "var(--text-muted)", fontWeight: 700 }}>
          {isOpen ? "▲" : "▼"}
        </span>
      </div>

      {/* ── Body ── */}
      {isOpen && (
        <div id={`section-body-${id}`} style={{ padding: bodyPad }}>
          {children}
        </div>
      )}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// ── StatusDot — small filled/empty indicator shown in every sidebar section header.
//    active = true  → glowing green dot (section has non-default user data)
//    active = false → dim grey ring  (section is at default/empty state)
// ─────────────────────────────────────────────────────────────────────────────
function StatusDot({ active }) {
  return (
    <span
      title={active ? "Has user data" : "No data entered yet"}
      style={{
        display: "inline-block",
        width: 7,
        height: 7,
        borderRadius: "50%",
        marginLeft: 6,
        flexShrink: 0,
        background: active ? "var(--clr-green)" : "transparent",
        border: active ? "1.5px solid var(--clr-green)" : "1.5px solid var(--border-strong)",
        boxShadow: active ? "0 0 5px rgba(var(--clr-emerald-rgb),0.55)" : "none",
        transition: "all 0.2s",
      }}
    />
  );
}

